package sfz.redis.l07.demo;

import redis.clients.jedis.RedisClient;

import java.util.List;

/** A token bucket in Lua: 10 tokens, one new token every 500 ms. A burst of 15, then one request every 250 ms. */
public class TokenBucketDemo {
    // KEYS[1] the bucket (a hash with tokens and ts). ARGV[1] capacity, ARGV[2] ms per new token, ARGV[3] now in ms.
    static final String TOKEN_BUCKET = """
            local capacity = tonumber(ARGV[1])
            local interval = tonumber(ARGV[2])
            local now = tonumber(ARGV[3])
            local b = redis.call('HMGET', KEYS[1], 'tokens', 'ts')
            local tokens, ts = tonumber(b[1]), tonumber(b[2])
            if tokens == nil then                                -- a bucket nobody used yet starts full
                tokens, ts = capacity, now
            end
            local earned = math.floor((now - ts) / interval)     -- whole tokens since ts
            if earned > 0 then
                tokens = math.min(capacity, tokens + earned)
                ts = ts + earned * interval                      -- keep the part of a token not earned yet
            end
            local allowed = 0
            if tokens > 0 then
                tokens = tokens - 1
                allowed = 1
            end
            redis.call('HSET', KEYS[1], 'tokens', tokens, 'ts', ts)
            redis.call('PEXPIRE', KEYS[1], capacity * interval)  -- idle that long, it is full again: forget it
            return allowed
            """;

    static final String KEY = "demo:l07:bucket:merchant:m-17";

    static boolean take(RedisClient redis, long now) {
        Object r = redis.eval(TOKEN_BUCKET, List.of(KEY), List.of("10", "500", String.valueOf(now)));
        return Long.valueOf(1).equals(r);
    }

    public static void main(String[] args) {
        try (RedisClient redis = RedisClient.builder().hostAndPort("localhost", 6379).build()) {
            redis.del(KEY);
            long t0 = 1_762_500_000_000L;                     // a pretend clock, passed in, so every run is the same

            int burst = 0;
            for (int i = 0; i < 15; i++) if (take(redis, t0)) burst++;
            System.out.printf("t = 0.00 s     a burst of 15:                  %2d admitted, %d refused%n", burst, 15 - burst);

            StringBuilder line = new StringBuilder();
            int steady = 0;
            for (int i = 1; i <= 20; i++) {
                boolean ok = take(redis, t0 + i * 250L);
                if (ok) steady++;
                line.append(ok ? '+' : '.');
            }
            System.out.printf("t = 0.25-5.00  one request every 250 ms:       %2d of 20 admitted  %s%n", steady, line);

            int afterRest = 0;
            for (int i = 0; i < 15; i++) if (take(redis, t0 + 10_000)) afterRest++;
            System.out.printf("t = 10.00 s    another burst of 15, after 5 s: %2d admitted%n", afterRest);
            System.out.println("bucket: " + redis.hgetAll(KEY) + ", PTTL " + redis.pttl(KEY) + " ms");
        }
    }
}

