record Reply(int status, String body) {}

// POST /payments: the Idempotency-Key header and the raw JSON body
Reply charge(String idemKey, String requestJson) {
    String hash = sha256(requestJson);                        // same body, same hash
    IdempotencyStore.Begin begin = store.begin(idemKey, hash);
    if (begin instanceof IdempotencyStore.Begin.Replay replay) return new Reply(200, replay.getResponse());
    if (begin instanceof IdempotencyStore.Begin.InProgress) return new Reply(409, "{\"error\":\"in progress\"}");
    if (begin instanceof IdempotencyStore.Begin.Mismatch) return new Reply(422, "{\"error\":\"key reused\"}");
    IdempotencyStore.Begin.Started started = (IdempotencyStore.Begin.Started) begin;
    String response = issuer.authorize(requestJson);          // the side effect, once per key
    store.complete(idemKey, hash, started.getToken(), response);
    return new Reply(200, response);
}

